@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private List<ThreadSummary> threadSummaries = [];
    private List<Message> threadReplies = [];
    private Message? threadRootMessage;

    private int selectedChannelId;
    private bool isThreadOpen;
    private bool hasMoreMessages;
    private bool isLoadingMore;
    private const int PageSize = 30;

    private Channel? SelectedChannel => channels.FirstOrDefault(c => c.Id == selectedChannelId);
    private string MessageAreaCssClass => isThreadOpen ? "message-area-with-thread" : "message-area-full";

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        hasMoreMessages = messages.Count == PageSize;
        threadSummaries = GetThreadSummaries(messages);
        await ChatService.MarkChannelReadAsync(channelId);

        // Close any open thread when switching channels
        isThreadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore) return;
        isLoadingMore = true;

        var olderMessages = await ChatService.GetMessagesAsync(selectedChannelId, messages.Count, PageSize);
        hasMoreMessages = olderMessages.Count == PageSize;
        messages.InsertRange(0, olderMessages);
        threadSummaries = GetThreadSummaries(messages);

        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        var message = await ChatService.SendMessageAsync(selectedChannelId, content, null);
        messages.Add(message);
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        threadReplies = await ChatService.GetThreadAsync(messageId);
        isThreadOpen = true;
    }

    private void CloseThread()
    {
        isThreadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannelId, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        // Update thread summary count
        threadSummaries = GetThreadSummaries(messages, threadRootMessage.Id, threadReplies.Count);
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to show updated reaction
        messages = await ChatService.GetMessagesAsync(selectedChannelId, 0, messages.Count);
    }

    private List<ThreadSummary> GetThreadSummaries(List<Message> msgs, int? updatedThreadId = null, int? updatedCount = null)
    {
        var summaries = msgs
            .Where(m => m.ReplyToId is null)
            .Select(m =>
            {
                var replies = msgs.Where(r => r.ReplyToId == m.Id).ToList();
                if (replies.Count == 0 && !(updatedThreadId == m.Id && updatedCount > 0))
                    return null;
                var count = updatedThreadId == m.Id ? updatedCount!.Value : replies.Count;
                var lastReply = replies.Count > 0 ? replies.Max(r => r.SentAt) : DateTime.UtcNow;
                return new ThreadSummary(m.Id, count, lastReply);
            })
            .Where(s => s is not null)
            .Cast<ThreadSummary>()
            .ToList();

        return summaries;
    }
}

